gC0(){return"\u05d4\u05e2\u05dc\u05d0\u05ea \u05d5\u05d9\u05d6\u05d4"},
gC_(){return"\u05d4\u05e2\u05dc\u05d5 \u05d0\u05ea \u05d4\u05d5\u05d5\u05d9\u05d6\u05d4 \u05db\u05e7\u05d5\u05d1\u05e5 PDF \u05d5\u05d4\u05d6\u05d9\u05e0\u05d5 \u05d0\u05ea \u05ea\u05d0\u05e8\u05d9\u05da \u05d4\u05ea\u05d5\u05e7\u05e3 \u05e9\u05db\u05ea\u05d5\u05d1 \u05d1\u05d4."},
