ga2D(){return"\u05de\u05e1\u05e4\u05e8 \u05d4\u05d1\u05e7\u05e9\u05d4"},
ga2C(){return"\u05de\u05d5\u05e2\u05d3 \u05d4\u05d1\u05e7\u05e9\u05d4"},
