ga2p(){return"\u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9 \u05e0\u05d9\u05e1\u05d9\u05d5\u05e0\u05d5\u05ea \u05e2\u05dd \u05d4\u05e7\u05d5\u05d3 \u05d4\u05d6\u05d4. \u05d1\u05e7\u05e9\u05d5 \u05e7\u05d5\u05d3 \u05d7\u05d3\u05e9"},
ga2c(){return"\u05db\u05d1\u05e8 \u05e7\u05d9\u05d9\u05de\u05ea \u05d1\u05e7\u05e9\u05ea \u05de\u05d7\u05d9\u05e7\u05d4 \u05dc\u05d7\u05e9\u05d1\u05d5\u05df \u05d4\u05d6\u05d4"},
ga2b(){return"\u05d4\u05d1\u05e7\u05e9\u05d4 \u05d4\u05e7\u05d5\u05d3\u05de\u05ea \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc. \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05ea \u05d4\u05e1\u05d8\u05d8\u05d5\u05e1 \u05d1\u05e7\u05d9\u05e9\u05d5\u05e8 \u05e9\u05e9\u05de\u05e8\u05ea\u05dd, \u05d0\u05d5 \u05dc\u05e4\u05e0\u05d5\u05ea \u05dc\u05ea\u05de\u05d9\u05db\u05d4"},
a2X(a){return A.bx(a,null,this.a,null,"\u05e9\u05dc\u05d1 \u05d0\u05d7\u05d3 \u05e2\u05d5\u05d3 \u05d1\u05d1\u05d9\u05e6\u05d5\u05e2",""+a+" \u05e9\u05dc\u05d1\u05d9\u05dd \u05e2\u05d5\u05d3 \u05d1\u05d1\u05d9\u05e6\u05d5\u05e2",null,"\u05db\u05dc \u05d4\u05e9\u05dc\u05d1\u05d9\u05dd \u05d4\u05e1\u05ea\u05d9\u05d9\u05de\u05d5")},
ga28(){return"\u05d4\u05d5\u05e9\u05dc\u05dd \u05d1"},
gEI(){return"\u05ea\u05e0\u05d0\u05d9 \u05e9\u05d9\u05de\u05d5\u05e9"},
ga3l(){return"\u05d4\u05d8\u05e7\u05e1\u05d8 \u05de\u05ea\u05d0\u05e8 \u05d1\u05e9\u05e4\u05d4 \u05e4\u05e9\u05d5\u05d8\u05d4 \u05d0\u05d9\u05da \u05d4\u05e9\u05d9\u05e8\u05d5\u05ea \u05de\u05ea\u05d5\u05db\u05e0\u05df \u05dc\u05e2\u05d1\u05d5\u05d3. \u05d4\u05d5\u05d0 \u05e2\u05d3\u05d9\u05d9\u05df \u05dc\u05d0 \u05e0\u05d1\u05d3\u05e7 \u05d1\u05d9\u05d3\u05d9 \u05e2\u05d5\u05e8\u05da \u05d3\u05d9\u05df, \u05d0\u05d9\u05e0\u05d5 \u05d9\u05d9\u05e2\u05d5\u05e5 \u05de\u05e9\u05e4\u05d8\u05d9 \u05d5\u05d0\u05d9\u05e0\u05d5 \u05d4\u05ea\u05d7\u05d9\u05d9\u05d1\u05d5\u05ea \u05de\u05e9\u05e4\u05d8\u05d9\u05ea"},
